#!/usr/bin/env sh
# bin/standard-vendor.sh (harbor#967 item 4, #1002): the naming package lands in vendor/naming/ with a manifest, and
# --check goes red on each kind of drift (stale, edited, missing, extra, new) and reads 3 where nothing is vendored.
. "$(dirname "$0")/../../lib/core.sh"; t_init
SV="$T_ROOT/bin/standard-vendor.sh"
H="$T_TMP/harbor"; R="$T_TMP/repo"
mkh() { rm -rf "$H"; mkdir -p "$H/bin" "$H/standards/naming"
  cp "$T_ROOT/bin/lint-name.sh" "$T_ROOT/bin/lint-renderer.sh" "$T_ROOT/bin/library-log.sh" "$T_ROOT/bin/standard-vendor.sh" "$H/bin/"
  cp "$T_ROOT"/standards/naming/*.tsv "$H/standards/naming/"; }
mkr() { rm -rf "$R"; mkdir -p "$R"; }
chk() { sh "$SV" --check --source "$H" "$R" 2>&1; }
mkh; mkr

t_section "vendoring writes the package, a header and one manifest row per file"
out="$(sh "$SV" --source "$H" "$R" 2>&1)"; rc=$?
t_eq "exit 0" 0 "$rc"
t_has "names the version" "$out" "vendored naming@"
M="$R/vendor/naming/MANIFEST.tsv"
t_has "header says generated" "$(sed -n 1p "$M")" "GENERATED by bin/standard-vendor.sh"
t_has "header carries the harbor commit line" "$(cat "$M")" "# harbor_commit: "
t_has "header carries standard_version" "$(cat "$M")" "# standard_version: 2."
t_has "a row for the lint" "$(cat "$M")" "lint-name.sh	"
t_has "a row for a registry file" "$(cat "$M")" "registry/terms.tsv	"
t_eq "one row per file" "$(find "$R/vendor/naming" -type f ! -name MANIFEST.tsv | wc -l | tr -d ' ')" "$(grep -vc '^#' "$M" | tr -d ' ')"

t_section "the vendored lint runs offline from the repo root"
out="$(cd "$R" && sh vendor/naming/lint-name.sh --root . --registry vendor/naming/registry --check path docs/reports/2026-10-03-review.md 2>&1)"; rc=$?
t_eq "a good name passes" 0 "$rc"
t_has "and says so" "$out" "no finding"

t_section "a current copy is green"
out="$(chk)"; rc=$?
t_eq "exit 0" 0 "$rc"; t_has "says current" "$out" "is current with harbor"

t_section "drift goes red, each kind by name (the red proof)"
echo '# edit' >> "$R/vendor/naming/registry/terms.tsv"
out="$(chk)"; rc=$?; t_eq "an edited vendored file exits 1" 1 "$rc"; t_has "named edited" "$out" "edited: vendor/naming/registry/terms.tsv"
mkr; sh "$SV" --source "$H" "$R" >/dev/null 2>&1
echo '# harbor moved' >> "$H/bin/lint-name.sh"
out="$(chk)"; rc=$?; t_eq "harbor ahead exits 1" 1 "$rc"; t_has "named stale" "$out" "stale: vendor/naming/lint-name.sh"
mkh; mkr; sh "$SV" --source "$H" "$R" >/dev/null 2>&1
rm "$R/vendor/naming/library-log.sh"
out="$(chk)"; rc=$?; t_eq "a missing file exits 1" 1 "$rc"; t_has "named missing" "$out" "missing: vendor/naming/library-log.sh"
mkr; sh "$SV" --source "$H" "$R" >/dev/null 2>&1
echo x > "$R/vendor/naming/stray.sh"
out="$(chk)"; rc=$?; t_eq "an extra file exits 1" 1 "$rc"; t_has "named extra" "$out" "extra: vendor/naming/stray.sh"
mkr; sh "$SV" --source "$H" "$R" >/dev/null 2>&1
printf 'x\tx\n' > "$H/standards/naming/newreg.tsv"
out="$(chk)"; rc=$?; t_eq "a file harbor added exits 1" 1 "$rc"; t_has "named new" "$out" "new: vendor/naming/registry/newreg.tsv"

t_section "re-vendoring heals the drift"
sh "$SV" --source "$H" "$R" >/dev/null 2>&1
out="$(chk)"; rc=$?; t_eq "green again" 0 "$rc"

t_section "unchecked and usage"
mkr; t_exit "nothing vendored is 3, never green" 3 sh "$SV" --check --source "$H" "$R"
t_exit "no repo" 2 sh "$SV"
t_exit "missing directory" 2 sh "$SV" "$T_TMP/nope"
t_exit "unknown flag" 2 sh "$SV" --nope
t_exit "--help" 0 sh "$SV" --help

t_section "a workload's CI checks its copy offline, with no harbor (harbor#967)"
mkh; mkr; sh "$SV" --source "$H" "$R" >/dev/null 2>&1
t_has "the checker ships in the package" "$(cat "$R/vendor/naming/MANIFEST.tsv")" "standard-vendor.sh	"
rm -rf "$H"   # no harbor anywhere: the workload's own copy is all there is
off() { (cd "$R" && sh vendor/naming/standard-vendor.sh --check --offline . 2>&1); }
out="$(off)"; rc=$?
t_eq "a clean copy is green offline" 0 "$rc"; t_has "...and says currency was not judged" "$out" "offline"
echo '# edit' >> "$R/vendor/naming/registry/terms.tsv"
out="$(off)"; rc=$?; t_eq "an edited file is red offline" 1 "$rc"; t_has "named edited" "$out" "edited: vendor/naming/registry/terms.tsv"
mkh; mkr; sh "$SV" --source "$H" "$R" >/dev/null 2>&1; rm -rf "$H"
rm "$R/vendor/naming/registry/terms.tsv"
out="$(off)"; rc=$?; t_eq "a missing file is red offline" 1 "$rc"; t_has "named missing" "$out" "missing: vendor/naming/registry/terms.tsv"
mkh; mkr; sh "$SV" --source "$H" "$R" >/dev/null 2>&1; rm -rf "$H"
: > "$R/vendor/naming/registry/stray.tsv"
out="$(off)"; rc=$?; t_eq "an extra file is red offline" 1 "$rc"; t_has "named extra" "$out" "extra: vendor/naming/registry/stray.tsv"
rm -f "$R/vendor/naming/MANIFEST.tsv"
t_exit "no manifest is unchecked (3), never green" 3 sh "$R/vendor/naming/standard-vendor.sh" --check --offline "$R"
t_exit "--offline never writes" 2 sh "$R/vendor/naming/standard-vendor.sh" --offline "$R"
t_done
